// z80_mame.cpp -- cpu.h's Z80 on MAME's Z80 core: the CORRECTED path (CONTRACT.md 1-2, 7, 9, 15).
//
// One translation unit: MAME's code (z80_mame_machine.cpp, generated by extract_z80_machine.py) is included here.
// Build this file; never z80_mame_machine.cpp alone.
//
// MAME's Z80 is generated from z80.lst as the whole body of execute_run: one loop whose first state (the .lst's
// `ffff`) looks at the interrupt lines, takes one, then fetches an opcode and dispatches; each instruction ends with a
// jump back to that state, and MAME stays in the loop while its time slice has T-states left.  After every bus
// cycle the loop can suspend (m_icount <= 0) and a later call resumes there.  A prefix (DDh, FDh, CBh, EDh) jumps on
// to its opcode without passing the first state, so no interrupt is taken between them, as on the chip.  What marks
// an instruction's end is the state number m_ref being 0xffff00 again.
//
// The driver is ours.  A step, in the contract's phases:
//   A  unless an instruction is being continued (below): a pass of execute_run that looks at the lines, upstream's
//      own test -- a latched NMI edge, else INT while IFF1 is set and the instruction before was not EI -- and
//      returns after at most one acceptance: the return address pushed, the acknowledge byte read (irq_ack, INT
//      only), the PC set; a halted core leaves HALT.  z80_pc() is the interrupted address: where execution resumes,
//      the PC that is pushed (after its HALT, for a halted core).
//   B  its T-states: NMI 11, INT 13 in mode 1 and 19 in mode 2 (upstream's = Zilog's); mode 0 as upstream counts the
//      five instructions it knows.
//   C  the EI delay ends: upstream clears its flag at the head of the fetch, which here is the head of E's pass.  No
//      callback can tell the difference: nothing between reads the flag.
//   D  steps++, the saved PC, bus->boundary.
//   E  a pass that does not look at the lines: one instruction from its first byte, prefixes included, to its last
//      T-state; or one HALT slot, the chip's NOP: an opcode fetch at the address after the HALT, its byte ignored,
//      4 T, R counted.  A block instruction (LDIR ...) is one repetition a step: upstream moves PC back onto it, as
//      the chip does, so an interrupt is taken between repetitions.
//   F  its T-states.  (No on-chip peripherals: G is empty.)
// The step limit: nothing ends a run of prefixes that never reaches an opcode (DDh DDh DDh ...: each is fetched,
// 4 T, and the next looked at), so in a memory full of them one step would go on for ever.  A pass is given
// Z80_STEP_LIMIT T-states; the longest instruction takes 23, so only such a run reaches it.  It is then suspended as
// MAME suspends at a slice's end, and the next step continues it: no acceptance in between (the chip takes none
// after a prefix), the saved PC unchanged.
//
// Differences from MAME, each deliberate (the generated file marks those made there 'CHANGED'):
//   - An instruction is never split by a time slice: a step runs it to its end (but for the case above).
//   - The lines are looked at in a step's A only, and A accepts at most one interrupt: then the boundary, then the
//     handler's first instruction.  MAME goes from the acceptance straight into the fetch.
//   - Reset sets interrupt mode 0 (Zilog's manual, the RESET pin: "sets the interrupt status to Mode 0"); MAME's
//     device_reset leaves the mode.  Reset's own T-states are not counted.
//   - An NMI edge is latched whenever the line goes from released to asserted, before the first step too; MAME drops
//     one that comes at its machine's time 0.
//   - The acknowledge cycle's data bus is cpu_bus.irq_ack (byte 0; for a CALL or JP in mode 0, bytes 1 and 2 too);
//     MAME asks its daisy chain or the framework.  No daisy chain: RETI tells no device.
//   - assert sets z80_regs.fault (MAME aborts, or in a release build loops); the core then does 4-T slots until reset.
//   - z80_regs_set and z80_next_pc, for a host that calls into its program (MAME has its debugger's state interface,
//     not taken): the registers written between steps, HALT, the EI delay and any cut instruction left.
// Kept from MAME, and stated because the chip or the manual may differ (CONTRACT.md 15): mode 0 knows NOP, RST,
// CALL, JP and EI and does nothing for another byte; NMI is taken at the boundary after EI (only INT waits); the
// undocumented opcodes and flags are upstream's, a ZiLOG NMOS part's by its own account (OUT (C),0 writes 00h).
// Not modelled: the WAIT, BUSREQ and RESET pins as lines (upstream's code for the first two is there; cpu.h reaches
// neither), the refresh address, and bus cycles at their own T-states (CONTRACT.md 7).
#include <cstddef>
#include <new>

#include "z80_mame_machine.cpp"

// The T-states a pass may take before it is suspended (the header: only a run of prefixes gets there).
static const int Z80_STEP_LIMIT = 64;

// ---- the driver's piece, as a member ---------------------------------------------------------------------------

// execute_run from the state m_ref names until it is back at the instruction boundary (an acceptance pass ends
// there taken or not; the other pass after one instruction or HALT slot) or the limit is reached.  `enter`: the pass
// starts at a boundary and may go in once; without it, it continues a cut instruction and ends at its boundary.
// Returns the T-states it took.
int z80_device::drv_pass(bool accept, bool enter)
{
    m_icount = Z80_STEP_LIMIT;
    m_drv_accept = accept;
    m_drv_enter = enter;
    execute_run();
    return Z80_STEP_LIMIT - m_icount;
}

// ---- cpu.h ------------------------------------------------------------------------------------------------------

struct z80 {
    cpu_bus bus;
    z80_device *dev;
    uint64_t cycles, steps;
    uint32_t pc;
};

extern "C" {

z80 *z80_create(const cpu_bus *bus, double clock_hz)
{
    (void)clock_hz;                           // the core counts T-states; the board turns them into time
    if (!bus || !bus->read || !bus->write || !bus->in || !bus->out)
        return nullptr;
    z80 *c = new (std::nothrow) z80();
    if (!c)
        return nullptr;
    c->bus = *bus;
    c->dev = new (std::nothrow) z80_device(&c->bus);
    if (!c->dev) {
        delete c;
        return nullptr;
    }
    c->dev->init_state();                     // MAME's power-on values: IX = IY = FFFFh, Z set, the rest 0
    z80_reset(c);
    return c;
}

void z80_destroy(z80 *c)
{
    if (!c)
        return;
    delete c->dev;
    delete c;
}

// Reset (CONTRACT.md 9): MAME's device_reset -- out of HALT, PC = 0, I = R = 0, IFF1 = IFF2 = 0, a latched NMI edge
// and the EI delay dropped, any cut instruction left; the other registers keep their values -- and interrupt mode 0,
// which the chip's RESET sets and upstream's leaves alone.  The lines are kept: a held INT is sampled again at the
// next A; a held NMI line is no new edge.
void z80_reset(z80 *c)
{
    z80_device &d = *c->dev;
    d.device_reset();
    d.m_im = 0;
    d.m_prvpc = d.m_pc;
    d.m_drv_fault = false;
    c->cycles = c->steps = 0;
    c->pc = d.m_pc.w;
}

int z80_step(z80 *c)
{
    z80_device &d = *c->dev;
    // an instruction being continued: a run of prefixes the limit cut (the header)
    bool inside = d.m_ref != 0xffff00;
    int acc = 0;
    // A's callbacks (the stack writes, the acknowledge) see the interrupted address: where execution resumes
    c->pc = inside ? d.m_prvpc.w : d.m_pc.w;
    if (!inside && d.m_service_attention && !d.m_drv_fault)   // A
        acc = d.drv_pass(true, true);
    c->cycles += (uint64_t)acc;               // B

    c->steps++;                               // D
    if (!inside)                              // (a continued instruction keeps its start; a halted core's PC is
        c->pc = (uint16_t)(d.m_pc.w - (d.m_halt ? 1 : 0));   // after its HALT: the slot's is the HALT)
    if (c->bus.boundary)
        c->bus.boundary(c->bus.ctx, c->pc);

    int ins = d.m_drv_fault ? 4 : d.drv_pass(false, !inside);   // C, E
    c->cycles += (uint64_t)ins;               // F
    return acc + ins;
}

uint64_t z80_run(z80 *c, uint64_t budget)
{
    uint64_t done = 0;
    while (done < budget)
        done += (uint64_t)z80_step(c);
    return done;
}

void z80_set_irq(z80 *c, int line, int asserted)
{
    int state = asserted ? ASSERT_LINE : CLEAR_LINE;
    if (line == Z80_INT)
        c->dev->execute_set_input(INPUT_LINE_IRQ0, state);
    else if (line == Z80_NMI)
        c->dev->execute_set_input(INPUT_LINE_NMI, state);
}

uint64_t z80_cycles(const z80 *c) { return c->cycles; }
uint64_t z80_steps(const z80 *c) { return c->steps; }
uint32_t z80_pc(const z80 *c) { return c->pc; }
uint32_t z80_next_pc(const z80 *c) { return c->dev->m_pc.w; }

void z80_regs_get(const z80 *c, z80_regs *out)
{
    z80_device &d = *c->dev;
    // upstream keeps the flags apart (m_f) and makes F when it is wanted: PUSH AF and EX AF,AF' do the same
    out->af = (uint16_t)(d.m_af.b.h << 8 | d.get_f());
    out->bc = d.m_bc.w; out->de = d.m_de.w; out->hl = d.m_hl.w;
    out->af2 = d.m_af2.w; out->bc2 = d.m_bc2.w; out->de2 = d.m_de2.w; out->hl2 = d.m_hl2.w;
    out->ix = d.m_ix.w; out->iy = d.m_iy.w; out->sp = d.m_sp.w; out->pc = d.m_pc.w;
    out->i = d.m_i;
    out->r = (uint8_t)((d.m_r & 0x7f) | (d.m_r2 & 0x80));   // 7 bits count; bit 7 is what LD R,A put there
    out->im = d.m_im;
    out->iff1 = d.m_iff1 ? 1 : 0;
    out->iff2 = d.m_iff2 ? 1 : 0;
    out->halted = d.m_halt ? 1 : 0;
    out->fault = d.m_drv_fault ? 1 : 0;
}

void z80_regs_set(z80 *c, const z80_regs *in)
{
    z80_device &d = *c->dev;
    d.m_af.w = in->af;
    d.set_f((uint8_t)in->af);
    d.m_bc.w = in->bc; d.m_de.w = in->de; d.m_hl.w = in->hl;
    d.m_af2.w = in->af2; d.m_bc2.w = in->bc2; d.m_de2.w = in->de2; d.m_hl2.w = in->hl2;
    d.m_ix.w = in->ix; d.m_iy.w = in->iy; d.m_sp.w = in->sp; d.m_pc.w = in->pc;
    d.m_i = in->i;
    d.m_r = in->r & 0x7f;
    d.m_r2 = in->r & 0x80;
    d.m_im = in->im > 2 ? 2 : in->im;
    d.m_iff1 = in->iff1 != 0;
    d.m_iff2 = in->iff2 != 0;
    // out of HALT, of the EI delay and of any cut instruction: the next step starts a new instruction at the PC
    // given (as upstream's state_import does when its debugger sets PC)
    d.leave_halt();
    d.set_service_attention<z80_device::SA_AFTER_EI, 0>();
    d.m_ref = 0xffff00;
    d.m_prvpc = d.m_pc;
    c->pc = in->pc;
}

}  // extern "C"
